refentry.refsect1:
&reftitle.description;
intfalsefileperms stringfilename
指定したファイルのパーミッションを取得します。

&reftitle.parameters;




   filename



     ファイルへのパス。

  &reftitle.examples;



    八進形式でのパーミッションの表示


<?php
echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);
?>


    &example.outputs;


1777
0644




    完全なパーミッションの表示


<?php
$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // FIFO パイプ
    case 0x2000: $info = 'c'; break; // キャラクタスペシャルファイル
    case 0x4000: $info = 'd'; break; // ディレクトリ
    case 0x6000: $info = 'b'; break; // ブロックスペシャルファイル
    case 0x8000: $info = 'r'; break; // 通常のファイル
    case 0xA000: $info = 'l'; break; // シンボリックリンク
    case 0xC000: $info = 's'; break; // ソケット

    // 不明
    default: $info = 'u';
}

// 所有者
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// グループ
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// 全体
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;
?>


    &example.outputs;


-rw-r--r--
